css:
/* Tudo depende da classe .reveal-on na raiz, que o JS só adiciona quando o
   sistema não pede menos movimento — sem ela nada é escondido, então a página
   funciona igual com JS desligado. */
.reveal-on [data-reveal] > * {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.7s cubic-bezier(0.22, 1, 0.36, 1),
              transform 0.7s cubic-bezier(0.22, 1, 0.36, 1);
  transition-delay: var(--reveal-delay, 0ms);
}
.reveal-on [data-reveal].is-revealed > * {
  opacity: 1;
  transform: none;
}

/* Os filhos em cascata herdam o próprio atraso, calculado no JS. */
.reveal-on [data-reveal] [data-reveal-stagger] > * {
  opacity: 0;
  transform: translateY(18px);
  transition: opacity 0.6s cubic-bezier(0.22, 1, 0.36, 1),
              transform 0.6s cubic-bezier(0.22, 1, 0.36, 1);
  transition-delay: var(--reveal-delay, 0ms);
}
.reveal-on [data-reveal].is-revealed [data-reveal-stagger] > * {
  opacity: 1;
  transform: none;
}

section { padding: 90px 40px; border-bottom: 1px solid var(--border); max-width: 1360px; margin: 0 auto; }
.demo-eyebrow { font-size: 12px; color: var(--accent); letter-spacing: 0.2em; text-transform: uppercase; margin-bottom: 24px; }
.demo-heading { font-weight: 600; font-size: clamp(26px, 3.5vw, 40px); letter-spacing: -0.03em; }
.demo-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 16px; margin-top: 32px; }
.demo-card {
  background: var(--bg-alt); border: 1px solid var(--border); border-radius: 12px;
  padding: 32px; font-family: 'JetBrains Mono', monospace; font-size: 12px; color: var(--text-dim);
}

js:
export function initReveal() {
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

  const alvos = document.querySelectorAll('[data-reveal]');
  if (!alvos.length || !('IntersectionObserver' in window)) return;

  document.documentElement.classList.add('reveal-on');

  const observer = new IntersectionObserver(function (entries) {
    entries.forEach(function (entry) {
      if (!entry.isIntersecting) return;
      entry.target.classList.add('is-revealed');
      observer.unobserve(entry.target);
    });
  }, {
    // Dispara um pouco antes de encostar na borda, para o movimento já estar
    // acontecendo quando o olho chega.
    rootMargin: '0px 0px -12% 0px',
    threshold: 0.05
  });

  alvos.forEach(function (alvo) {
    const filhos = alvo.querySelectorAll('[data-reveal-stagger] > *');
    filhos.forEach(function (filho, i) {
      filho.style.setProperty('--reveal-delay', (i * 70) + 'ms');
    });
    observer.observe(alvo);
  });
}
